public class CustomerLoyaltyActivity extends CustomerAdaptiveActivity{
 private static final String URL="https://transiva.my.id/server/customer_loyalty.php", REDEEM="https://transiva.my.id/server/customer_loyalty_redeem.php";
 private LinearLayout root; private ProgressBar loading; private JSONObject data; private boolean redeemBusy; private String redeemKey=""; private int redeemRewardId;
 @Override protected void onCreate(Bundle b){super.onCreate(b);CustomerWindowPolicy.status(getWindow(), Color.parseColor(isDark()?"#07111F":"#075ED1"));CustomerWindowPolicy.appearance(getWindow(), isDark()?0:CustomerWindowPolicy.LIGHT_NAVIGATION);setContentView(base());CustomerAppSettings.apply(this);load();}

    @Override protected void onResume(){ super.onResume(); CustomerAppSettings.apply(this); if(data!=null)load(); }
 private View base(){ScrollView s=new ScrollView(this);s.setFillViewport(true);s.setBackgroundColor(Color.parseColor(isDark()?"#08111F":"#F4F7FC"));root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(18),dp(18),dp(36));s.addView(root);TextView h=tx("‹   Poin Transiva",24,"#0B3A78",true);h.setOnClickListener(v->finish());root.addView(h);root.addView(tx("Selesaikan misi, kumpulkan poin, pilih hadiahmu",13,"#64748B",false));loading=new ProgressBar(this, null, android.R.attr.progressBarStyleHorizontal);LinearLayout.LayoutParams l=new LinearLayout.LayoutParams(-2,-2);l.gravity=Gravity.CENTER;l.setMargins(0,dp(30),0,0);root.addView(loading,l);return s;}
 private void load(){TransivaNetworkExecutor.execute(()->{try{JSONObject o=request(URL,null);runOnUiThread(()->render(o));}catch(Exception e){String m=e.getMessage();runOnUiThread(()->error("Gagal memuat Royalti"+(m==null||m.trim().isEmpty()?".":": "+m)));}});}
 private void render(JSONObject o){loading.setVisibility(View.GONE);while(root.getChildCount()>3)root.removeViewAt(3);if(!o.optBoolean("success")){error(o.optString("message","Gagal memuat Royalti"));return;}data=o.optJSONObject("data");if(data==null)data=new JSONObject();
  int points=data.optInt("points_balance",data.optInt("points")),lifetime=data.optInt("earned_points",points),seasonPoints=data.optInt("season_points",0);
  String activeTier=data.optString("season_tier",data.optString("tier","BRONZE"));String lifetimeTier=data.optString("lifetime_tier",activeTier);
  JSONObject season=data.optJSONObject("season");String seasonLabel=season==null?"Season aktif":season.optString("label","Season aktif");String seasonRange=season==null?"":season.optString("start","")+" s/d "+season.optString("end","");

  LinearLayout hero=card("#0878F9",26);LinearLayout heroRow=new LinearLayout(this);heroRow.setGravity(Gravity.CENTER_VERTICAL);ImageView activeIcon=tierImage(activeTier,74);TierBadgeUi.enableShine(activeIcon,activeTier);heroRow.addView(activeIcon,new LinearLayout.LayoutParams(dp(74),dp(74)));LinearLayout heroText=new LinearLayout(this);heroText.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams htp=new LinearLayout.LayoutParams(0,-2,1);htp.setMargins(dp(14),0,0,0);heroText.addView(tx(activeTier+" MEMBER",15,"#DDF2FF",true));heroText.addView(tx(fmt(points)+" poin",29,"#FFFFFF",true));heroText.addView(tx("Saldo Poin Transiva",12,"#EAF4FF",false));heroRow.addView(heroText,htp);hero.addView(heroRow);hero.addView(tx(data.optString("card_progress",data.optString("season_next_tier_text","")),13,"#FFFFFF",true),margin(12));hero.addView(tx(data.optString("card_benefit"),12,"#EAF4FF",false),margin(8));root.addView(hero,margin(18));

  addMissions(data.optJSONArray("missions"));
  LinearLayout seasonCard=card("#FFFFFF",22);seasonCard.addView(tx("Status periode ini",17,"#0B3A78",true));seasonCard.addView(tx(seasonRange,12,"#64748B",false));addTierTrackInto(seasonCard,seasonPoints,data.optJSONArray("season_tiers"));root.addView(seasonCard,margin(14));

  LinearLayout life=card("#FFFFFF",22);LinearLayout lr=new LinearLayout(this);lr.setGravity(Gravity.CENTER_VERTICAL);ImageView lifetimeIcon=tierImage(lifetimeTier,62);TierBadgeUi.enableShine(lifetimeIcon,lifetimeTier);lr.addView(lifetimeIcon,new LinearLayout.LayoutParams(dp(62),dp(62)));LinearLayout lt=new LinearLayout(this);lt.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams ltp=new LinearLayout.LayoutParams(0,-2,1);ltp.setMargins(dp(14),0,0,0);lt.addView(tx("Pencapaian selama ini",17,"#0B3A78",true));lt.addView(tx(lifetimeTier+" • "+fmt(lifetime)+" poin",20,"#0F172A",true));lt.addView(tx("Poin pencapaian ini tetap tersimpan.",12,"#64748B",false));lr.addView(lt,ltp);life.addView(lr);life.addView(tx(data.optString("lifetime_next_tier_text",""),12,"#475569",false),margin(10));life.addView(tx("Poin tersedia untuk ditukar: "+fmt(points),12,"#0878F9",true),margin(8));root.addView(life,margin(14));

  LinearLayout expl=card("#FFFFFF",22);expl.addView(tx("Cara kerja poin dan status",17,"#0B3A78",true));expl.addView(tx("Poin dari misi dan pesanan masuk ke satu saldo. Gunakan poin untuk potongan pembayaran atau tukarkan voucher. Untuk potongan langsung, 1 poin = Rp1. "+(data.optBoolean("transaction_points_enabled")?"Setiap Rp"+fmt(data.optInt("spend_per_point",1000))+" mendapat "+fmt(data.optInt("points_per_unit",1))+" poin dasar, sebelum bonus level. ":"")+"Status anggota dihitung dari poin yang dikumpulkan selama "+(season==null?6:season.optInt("duration_months",6))+" bulan. Pemakaian poin tidak menurunkan level.",13,"#475569",false));root.addView(expl,margin(14));

  TextView title=tx("Voucher Poin Transiva",20,"#0B3A78",true);title.setPadding(0,dp(22),0,dp(4));root.addView(title);root.addView(tx("Pilihan voucher mengikuti status anggota saat ini. Penukaran memakai poin yang masih tersedia.",13,"#64748B",false));
  JSONArray rewards=data.optJSONArray("rewards");if(rewards==null||rewards.length()==0){root.addView(tx("Katalog voucher belum tersedia.",13,"#B45309",true),margin(12));}else for(int i=0;i<rewards.length();i++){JSONObject r=rewards.optJSONObject(i);if(r!=null)addReward(r,points);}
  JSONArray owned=data.optJSONArray("owned_vouchers");if(owned!=null&&owned.length()>0){root.addView(tx("Voucher Saya",20,"#0B3A78",true),margin(22));for(int i=0;i<owned.length();i++){JSONObject v=owned.optJSONObject(i);LinearLayout c=card("#ECFDF5",18);c.addView(tx(v.optString("title"),15,"#065F46",true));c.addView(tx(v.optString("voucher_code"),19,"#047857",true));c.addView(tx("Berlaku sampai "+v.optString("expires_at","-"),11,"#475569",false));c.addView(tx("Min. transaksi "+rupiah(v.optInt("min_order")),12,"#475569",false),margin(8));Button use=new Button(this);use.setAllCaps(false);use.setText("Gunakan");use.setOnClickListener(view->useVoucher(v.optString("voucher_code")));c.addView(use,new LinearLayout.LayoutParams(-1,dp(48)));root.addView(c,margin(10));}}
 }
 private void addTierTrackInto(LinearLayout c,int currentPoints,JSONArray rules){String[] n={"BRONZE","SILVER","GOLD","DIAMOND","PLATINUM"};int[] p={0,500,1500,3000,5000};if(rules!=null){for(int i=0;i<Math.min(rules.length(),5);i++){JSONObject r=rules.optJSONObject(i);if(r!=null){n[i]=r.optString("name",n[i]);p[i]=r.optInt("points",p[i]);}}}LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(15),0,0);for(int i=0;i<n.length;i++){LinearLayout col=new LinearLayout(this);col.setOrientation(LinearLayout.VERTICAL);col.setGravity(Gravity.CENTER);ImageView icon=tierImage(n[i],34);if(currentPoints<p[i])icon.setAlpha(.32f);col.addView(icon,new LinearLayout.LayoutParams(dp(34),dp(34)));col.addView(tx(titleCase(n[i]),9,"#334155",true));col.addView(tx(fmt(p[i]),9,"#94A3B8",false));row.addView(col,new LinearLayout.LayoutParams(0,-2,1));}c.addView(row);int floor=0,target=p[4];for(int k=0;k<p.length;k++){if(currentPoints>=p[k])floor=p[k];else{target=p[k];break;}}if(currentPoints>=p[4])floor=0;int max=Math.max(1,target-floor);ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(max);bar.setProgress(Math.min(max,Math.max(0,currentPoints-floor)));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(7));bp.setMargins(dp(8),dp(8),dp(8),0);c.addView(bar,bp);}
 private ImageView tierImage(String tier,int size){ImageView v=new ImageView(this);v.setScaleType(ImageView.ScaleType.CENTER_INSIDE);String key="tier_"+tier.toLowerCase(Locale.US);int id=getResources().getIdentifier(key,"drawable",getPackageName());if(id!=0){v.setImageResource(id);}else{android.graphics.drawable.GradientDrawable g=new android.graphics.drawable.GradientDrawable();g.setShape(GradientDrawable.OVAL);g.setColor(Color.parseColor("#EAF4FF"));g.setStroke(dp(2),Color.parseColor("#0878F9"));v.setBackground(g);TextViewCompatFallback.apply(v,tier);}v.setContentDescription(titleCase(tier)+" tier");return v;}
 private static class TextViewCompatFallback{static void apply(ImageView v,String tier){v.setImageDrawable(null);}}
 private void addReward(JSONObject r,int points){boolean unlocked=r.optBoolean("unlocked"),can=r.optBoolean("can_redeem");int cost=r.optInt("points_cost"),remaining=r.optInt("quota_remaining",-1);LinearLayout c=card("#FFFFFF",22);TextView badge=tx((unlocked?"TERBUKA":"🔒 "+r.optString("min_tier"))+"  •  "+cost+" poin",11,unlocked?"#0878F9":"#94A3B8",true);c.addView(badge);c.addView(tx(r.optString("title"),18,"#0F172A",true));c.addView(tx(r.optString("description"),13,"#475569",false));String q=remaining<0?"Kuota tersedia":"Sisa kuota: "+remaining;c.addView(tx(q+"  •  Min. order "+rupiah(r.optInt("min_order")),11,"#64748B",false));Button b=new Button(this);b.setAllCaps(false);b.setText(can?"Tukar • "+cost+" poin":(!unlocked?"Naikkan status anggota":(points<cost?"Poin belum cukup":"Kuota habis")));b.setEnabled(can);b.setTextColor(Color.WHITE);b.setBackground(round(can?"#0878F9":"#94A3B8",16));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(48));lp.setMargins(0,dp(12),0,0);c.addView(b,lp);b.setOnClickListener(v->confirmRedeem(r));root.addView(c,margin(12));}
 private void confirmRedeem(JSONObject r){String terms=r.optString("terms_text","Voucher mengikuti syarat dan ketentuan Transiva.");new TransivaAlertDialogBuilder(this).setTitle("Konfirmasi Penukaran").setMessage(r.optString("title")+"\n\nBiaya: "+r.optInt("points_cost")+" poin\n\nS&K:\n"+terms+"\n\nPoin akan dipotong setelah Anda mengonfirmasi.").setNegativeButton("Batal",null).setPositiveButton("Tukar Voucher",(d,w)->redeem(r.optInt("id"))).show();}
 private void redeem(int id){if(redeemBusy)return;redeemBusy=true;if(redeemKey.isEmpty()||redeemRewardId!=id){String stored=getSharedPreferences("royalty_redeem_"+new SessionManager(this).getUserId(),0).getString("reward_"+id,"");redeemKey=stored.isEmpty()?java.util.UUID.randomUUID().toString():stored;redeemRewardId=id;getSharedPreferences("royalty_redeem_"+new SessionManager(this).getUserId(),0).edit().putString("reward_"+id,redeemKey).apply();}TransivaNetworkExecutor.execute(()->{try{JSONObject p=new JSONObject();p.put("reward_id",id);p.put("request_key",redeemKey);JSONObject o=request(REDEEM,p);runOnUiThread(()->{redeemBusy=false;if(isFinishing()||isDestroyed())return;boolean ok=o.optBoolean("success");if(ok){redeemKey="";getSharedPreferences("royalty_redeem_"+new SessionManager(this).getUserId(),0).edit().remove("reward_"+id).apply();}new TransivaAlertDialogBuilder(this).setTitle(ok?"Voucher siap dipakai":"Penukaran belum berhasil").setMessage(ok?"Voucher tersimpan di Voucher Saya. Tekan Gunakan untuk memilih layanan.":o.optString("message")).setPositiveButton(ok?"Gunakan":"OK",(d,w)->{if(ok){load();useVoucher(o.optString("voucher_code"));}}).setNegativeButton(ok?"Nanti":"Tutup",(d,w)->{if(ok)load();}).show();});}catch(Exception e){runOnUiThread(()->{redeemBusy=false;if(!isFinishing()&&!isDestroyed())error("Koneksi terputus. Coba tukar lagi; permintaan yang sama tidak memotong poin dua kali.");});}});}
 private void useVoucher(String code){new TransivaAlertDialogBuilder(this).setTitle("Mau pakai di layanan apa?").setItems(new String[]{"TransRide","TransCar","TransFood"},(d,w)->{Class<?> destination=w==0?TransRideActivity.class:w==1?PassengerCarActivity.class:TransFoodActivity.class;startActivity(new android.content.Intent(this,destination).putExtra("royalty_voucher_code",code));}).setNegativeButton("Nanti",null).show();}
 private void addMissions(JSONArray missions){root.addView(tx("Misi untukmu",20,"#0B3A78",true),margin(20));if(missions==null||missions.length()==0){root.addView(tx("Misi baru sedang disiapkan. Poin dan koinmu tetap tersimpan.",13,"#64748B",false),margin(10));return;}for(int i=0;i<missions.length();i++){JSONObject m=missions.optJSONObject(i);if(m==null)continue;String state=m.optString("status");boolean done="completed".equals(state);LinearLayout c=card(done?"#ECFDF5":"#FFFFFF",20);c.addView(tx(done?"✓ Hadiah sudah masuk":"expired".equals(state)?"Misi berakhir":"upcoming".equals(state)?"Segera dimulai":"MISI AKTIF",11,done?"#047857":"#0878F9",true));c.addView(tx(m.optString("title"),17,"#0F172A",true),margin(8));c.addView(tx(m.optString("description"),13,"#475569",false),margin(6));c.addView(tx("+"+fmt(m.optInt("reward_points"))+" poin",21,"#0878F9",true),margin(12));int target=Math.max(1,m.optInt("target_orders",1)),progress=m.optInt("progress");ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(target);bar.setProgress(Math.min(target,progress));c.addView(bar,new LinearLayout.LayoutParams(-1,dp(8)));c.addView(tx(m.optString("progress_text"),12,"#475569",true),margin(8));c.addView(tx("Mulai "+m.optString("starts_at")+"\nBerakhir "+m.optString("ends_at"),11,"#64748B",false),margin(8));if(m.optInt("min_order_amount")>0)c.addView(tx("Minimum per pesanan "+rupiah(m.optInt("min_order_amount")),11,"#64748B",false),margin(5));if("active".equals(state)){Button order=new Button(this);order.setAllCaps(false);order.setText("Buat pesanan");order.setOnClickListener(v->{startActivity(new android.content.Intent(this,AllServicesActivity.class));});c.addView(order,new LinearLayout.LayoutParams(-1,dp(48)));}root.addView(c,margin(12));}}
 private JSONObject request(String u,JSONObject body)throws Exception{ return body==null ? TransivaHttpRepository.getJson(this,u,15000) : TransivaHttpRepository.postJson(this,u,body,15000); }
 private void error(String s){loading.setVisibility(View.GONE);TextView x=tx(s,14,"#B91C1C",true);root.addView(x,margin(16));}
 private boolean isDark(){return false; /* Preserve existing Royalti theme policy. */}
 private String themeColor(String c){if(!isDark())return c;String u=c.toUpperCase(Locale.US);if(u.equals("#FFFFFF"))return "#111C2C";if(u.equals("#0F172A")||u.equals("#0B3A78")||u.equals("#334155"))return "#F1F5F9";if(u.equals("#475569")||u.equals("#64748B"))return "#AFC0D4";if(u.equals("#94A3B8"))return "#7F93A9";if(u.equals("#ECFDF5"))return "#0D2A22";if(u.equals("#065F46")||u.equals("#047857"))return "#6EE7B7";if(u.equals("#B91C1C"))return "#FCA5A5";if(u.equals("#B45309"))return "#FCD34D";return c;}
 private LinearLayout card(String c,int r){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setPadding(dp(18),dp(18),dp(18),dp(18));x.setBackground(round(themeColor(c),r));return x;}private GradientDrawable round(String c,int r){GradientDrawable g=new GradientDrawable();g.setColor(Color.parseColor(themeColor(c)));g.setCornerRadius(dp(r));return g;}private LinearLayout.LayoutParams margin(int top){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(top),0,0);return p;}private TextView tx(String s,int z,String c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(Color.parseColor(themeColor(c)));t.setLineSpacing(0,1.12f);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}private String fmt(int n){return NumberFormat.getIntegerInstance(new Locale("id","ID")).format(n);}private String rupiah(int n){return "Rp"+fmt(n);}private String titleCase(String s){if(s==null||s.isEmpty())return "Bronze";s=s.toLowerCase(Locale.US);return Character.toUpperCase(s.charAt(0))+s.substring(1);}private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
}
